import {expect} from '@playwright/test';
import {imageDigest} from './text-ui.mjs';
export function invertCube(title='Invert'){return `TITLE "${title}"\nLUT_3D_SIZE 2\n`+[0,1].flatMap(b=>[0,1].flatMap(g=>[0,1].map(r=>`${1-r} ${1-g} ${1-b}`))).join('\n')+'\n';}
export async function exerciseLutUI(page,info,lang='zh',route='/#/tools/edit'){
  const t=(zh,en)=>lang==='en'?en:zh,photo=page.locator('.edit-image img'),sourceName=await photo.getAttribute('alt'),original=await imageDigest(photo),name=`LUT-${lang}-${page.viewportSize().width}.cube`,cube=invertCube(name);
  const panel=page.locator('.lut-panel');await panel.locator('summary').click();await panel.locator('input[type=file]').first().setInputFiles({name,mimeType:'application/octet-stream',buffer:Buffer.from(cube)});await panel.getByRole('searchbox').fill(name);
  const choice=panel.getByRole('button',{name:t('应用 LUT ','Apply LUT ')+name,exact:true});await expect(choice).toBeEnabled();await choice.click();await expect(choice).toHaveAttribute('aria-pressed','true');await expect.poll(()=>imageDigest(photo)).not.toBe(original);const graded=await imageDigest(photo);
  await expect(panel.locator('.lut-thumbnail img').first()).toBeVisible();await expect(panel.locator('.lut-thumbnail img').first()).toHaveJSProperty('naturalWidth',280);
  const strength=panel.getByRole('slider',{name:t('LUT 强度','LUT strength')});await strength.focus();await strength.press('Home');await expect.poll(()=>imageDigest(photo)).toBe(original);await strength.press('End');await expect.poll(()=>imageDigest(photo)).toBe(graded);
  await panel.getByRole('button',{name:t('收藏 LUT ','Favorite LUT ')+name,exact:true}).click();await expect(panel.getByRole('button',{name:t('收藏 LUT ','Favorite LUT ')+name,exact:true})).toHaveAttribute('aria-pressed','true');await panel.getByRole('combobox',{name:t('样式分组','Style group')}).selectOption('favorite');await expect(choice).toBeVisible();await panel.getByRole('combobox',{name:t('样式分组','Style group')}).selectOption('recent');await expect(choice).toBeVisible();
  await panel.getByRole('button',{name:t('移出 LUT ','Remove LUT ')+name,exact:true}).click();await expect(choice).toHaveCount(0);expect(await imageDigest(photo)).toBe(graded);await panel.getByRole('combobox',{name:t('样式分组','Style group')}).selectOption('hidden');await panel.getByRole('button',{name:t('恢复 LUT ','Restore LUT ')+name,exact:true}).click();await panel.getByRole('combobox',{name:t('样式分组','Style group')}).selectOption('all');await expect(choice).toBeVisible();
  const save=page.getByRole('button',{name:new RegExp('^'+t('保存编辑','Save edits'))});await save.click();await expect(save).toBeEnabled();await panel.getByRole('button',{name:t('移除当前 LUT','Clear current LUT'),exact:true}).click();await expect.poll(()=>imageDigest(photo)).toBe(original);await save.click();await expect(save).toBeEnabled();await page.getByRole('button',{name:t('撤销编辑','Undo edit'),exact:true}).click();await expect.poll(()=>imageDigest(photo)).toBe(graded);await save.click();await expect(save).toBeEnabled();
  expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:info.outputPath('lut-editor.png'),fullPage:true});await page.goto(route);await page.reload();await page.locator('.edit-records>div>button').filter({hasText:sourceName}).first().click();await expect.poll(()=>imageDigest(photo)).toBe(graded);await panel.locator('summary').click();await expect(panel.getByRole('slider',{name:t('LUT 强度','LUT strength')})).toHaveValue('1');return {sourceName,name,cube};
}
